def transpose_records(records):
    """Transpose a list of dicts into [key, column] pairs."""
    if not records:
        return []
    # Collect keys preserving record order and dict insertion order
    keys = []
    seen = set()
    for rec in records:
        for k in rec:
            if k not in seen:
                seen.add(k)
                keys.append(k)
    if not keys:
        return []
    # Build columns
    result = []
    for k in keys:
        col = [rec.get(k) for rec in records]
        result.append([k, col])
    return result
